function buildTree(preorder, inorder) {
  const map = new Map();
  for (let i = 0; i < inorder.length; i++) map.set(inorder[i], i);
  let preIdx = 0;
  const dfs = (lo, hi) => {
    if (lo > hi) return null;
    const root = new TreeNode(preorder[preIdx++]);
    root.left = dfs(lo, map.get(root.val) - 1);
    root.right = dfs(map.get(root.val) + 1, hi);
    return root;
  };
  return dfs(0, inorder.length - 1);
}

