function rotateRight(head, k) {
  if (!head || !head.next) return head;
  let tail = head, len = 1;
  while (tail.next) { tail = tail.next; len++; }
  k %= len;
  if (!k) return head;
  let steps = len - k - 1, curr = head;
  while (steps--) curr = curr.next;
  const newHead = curr.next;
  curr.next = null;
  tail.next = head;
  return newHead;
}

function numTrees(n) {
  const dp = new Array(n + 1).fill(0);
  dp[0] = dp[1] = 1;
  for (let i = 2; i <= n; i++)
    for (let j = 1; j <= i; j++)
      dp[i] += dp[j - 1] * dp[i - j];
  return dp[n];
}

function levelOrder(root) {
  if (!root) return [];
  const res = [], q = [root];
  while (q.length) {
    const level = [];
    const len = q.length;
    for (let i = 0; i < len; i++) {
      const node = q.shift();
      level.push(node.val);
      if (node.left) q.push(node.left);
      if (node.right) q.push(node.right);
    }
    res.push(level);
  }
  return res;
}

