function leastInterval(tasks, n) {
  const freq = {};
  for (const t of tasks) freq[t] = (freq[t] || 0) + 1;
  const maxFreq = Math.max(...Object.values(freq));
  const maxCount = Object.values(freq).filter(v => v === maxFreq).length;
  return Math.max(tasks.length, (maxFreq - 1) * (n + 1) + maxCount);
}

function rob(nums) {
  let prev = 0, curr = 0;
  for (const n of nums) [prev, curr] = [curr, Math.max(curr, prev + n)];
  return curr;
}

function rob(nums) {
  if (nums.length === 1) return nums[0];
  const robLine = (arr) => {
    let prev = 0, curr = 0;
    for (const n of arr) [prev, curr] = [curr, Math.max(curr, prev + n)];
    return curr;
  };
  return Math.max(robLine(nums.slice(0, -1)), robLine(nums.slice(1)));
}
